			const label = gutter ? "" : headText(th);
			const vals = [];
			const texts = [];
			bodyRows.forEach((r) => {
				const td = r.tr ? r.tr.children[c] : r.children[c];
				vals.push(cellEm(td));
				const t = cellLineText(td);
				if (t) texts.push(t);
			});
			const contentW = keepEm(vals);
			const headerW = textEm(label) * COL_HEAD_K;
